insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l1', (select id from public.learn_units where code = 'english-e3-u1'), '문장 만들기', '문장은 ''누가 → 무엇을 한다 → 무엇'' 순서예요. He, She, 사람 이름 뒤의 동사에는 **-s**를 붙여요.', 'She reads a book.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l1'), (select id from public.learn_skills where code = 'e.e3.build') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l2', (select id from public.learn_units where code = 'english-e3-u1'), '대명사', '이름 대신 **He**(그), **She**(그녀), **It**(그것), **They**(그들), **We**(우리)를 쓸 수 있어요.', 'Tom is tall. He is tall.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l2'), (select id from public.learn_skills where code = 'e.e3.pron') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l3', (select id from public.learn_units where code = 'english-e3-u1'), '현재형과 과거형', '지금이나 반복되는 일은 **현재형**, 지난 일은 동사 끝에 **-ed**를 붙인 **과거형**을 써요.', 'I walk. → I walked.', 2, 'PUBLISHED') on conflict (code) do nothing;
