insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l4', (select id from public.learn_units where code = 'english-e3-u1'), '하루 일과', 'get up, brush my teeth, eat breakfast, go to bed... 하루 일과를 영어로 말해 보세요.', 'I get up at seven.', 3, 'PUBLISHED') on conflict (code) do nothing;
