insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l5', (select id from public.learn_units where code = 'english-e6-u1'), '문단 읽기', '여러 문장으로 된 글을 읽고 누가·언제·왜 했는지 찾아 답해요.', 'Jina was tired because they walked a lot.', 4, 'PUBLISHED') on conflict (code) do nothing;
