insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l1', (select id from public.learn_units where code = 'en-m2-unit'), '현재완료', 'have/has + 과거분사. 경험, 완료, 계속을 나타내고, since(시점)와 for(기간)를 구별해요.', 'I have lived here for five years.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l1'), (select id from public.learn_skills where code = 'e.m2.perf') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l2', (select id from public.learn_units where code = 'en-m2-unit'), '수동태', 'be + 과거분사로 ''~되다/당하다'' 를 나타내요. 행위자는 by 로 덧붙여요.', 'The room is cleaned by Mina.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l2'), (select id from public.learn_skills where code = 'e.m2.pass') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l3', (select id from public.learn_units where code = 'en-m2-unit'), 'to부정사와 동명사', 'want, hope, decide + to부정사, enjoy, finish, avoid + 동명사. stop + to V 는 목적, stop + V-ing 는 중단이에요.', 'I want to buy a bike. She enjoys singing.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l3'), (select id from public.learn_skills where code = 'e.m2.inf') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l4', (select id from public.learn_units where code = 'en-m2-unit'), '비교급과 최상급', '-er/-est 와 more/most. 비교급에는 than, 최상급에는 the 를 써요. good → better → best 는 불규칙이에요.', 'hot → hotter → the hottest', 3, 'PUBLISHED') on conflict (code) do nothing;
